"""Draft concept extraction from Morrison's G2 paper and Morrison–Snyder's paper."""
import hashlib
import json
from pathlib import Path

ROOT=Path(__file__).resolve().parent
CONCEPTS,LINKS,EDGES,SOURCES,RELATIONS=[],[],[],[],[]


def concepts(field,text):
    for line in text.strip().splitlines():
        slug,kind,title,description,prereqs=line.split('|')
        CONCEPTS.append(dict(slug=slug,kind=kind,title=title,description=description,field=field,boundary=not prereqs,aliases=[]))
        for prereq in prereqs.split():
            EDGES.append(dict(prerequisite=prereq,dependent=slug,basis='both',rationale='The prerequisite enters the definition or the proof used in the cited paper.'))


concepts('Tensor categories', '''
linear-category|definition|Linear category|A category whose morphism spaces are vector spaces over a field k and whose composition is k-bilinear.|
monoidal-category|definition|Monoidal category|A category with a tensor product, a unit object, and coherent associativity and unit isomorphisms.|
rigid-category|definition|Rigid monoidal category|A monoidal category in which every object has left and right duals, with evaluation and coevaluation maps satisfying the zigzag identities.|monoidal-category
braided-category|definition|Braided monoidal category|A monoidal category with natural isomorphisms c(X,Y):X⊗Y→Y⊗X satisfying the two hexagon identities.|monoidal-category
pivotal-category|definition|Pivotal category|A rigid monoidal category with a monoidal natural isomorphism from the identity functor to the double-dual functor.|rigid-category
ribbon-category|definition|Ribbon category|A braided rigid monoidal category with a twist compatible with both the braiding and duality.|braided-category rigid-category
categorical-trace|definition|Categorical trace|The scalar obtained by closing an endomorphism using evaluation, coevaluation and a pivotal structure; left and right closures give left and right traces.|pivotal-category
karoubi-envelope|definition|Karoubi envelope of a category|The category obtained by formally splitting idempotent endomorphisms. Its objects are pairs (X,e) with e²=e; a map (X,e)→(Y,f) is a map a:X→Y with a=fae.|
negligible-morphism|definition|Negligible morphism|A morphism f:X→Y in a pivotal linear category is negligible if tr(gf)=0 for every g:Y→X.|categorical-trace linear-category
semisimplification|construction|Semisimplification|In the tensor categories considered here, quotient by the ideal of negligible morphisms and split idempotents to obtain a semisimple category.|negligible-morphism karoubi-envelope
simple-object|definition|Simple object in an abelian category|A nonzero object whose only subobjects are zero and itself.|
semisimple-category|definition|Semisimple category|An additive category in which every object is a finite direct sum of simple objects.|simple-object
split-simple|definition|Split simple object|A simple object X in a k-linear category is split if End(X)=k.|simple-object
split-semisimple|definition|Split semisimple category|A semisimple k-linear category in which every simple object is split.|semisimple-category split-simple
minimal-idempotent|definition|Primitive idempotent in an algebra|A nonzero idempotent that is not a sum of two nonzero orthogonal idempotents. In a semisimple algebra, it projects onto a simple summand.|
schur-lemma|theorem|Schur's lemma|A nonzero morphism between simple objects of an abelian category is an isomorphism. Consequently, the endomorphism ring of a simple object is a division ring.|simple-object
''')

concepts('Quantum groups / G2 webs', '''
braid-group|definition|Braid group|Bₙ is generated by σ₁,…,σₙ₋₁, with σᵢσⱼ=σⱼσᵢ for abs(i−j)>1 and σᵢσᵢ₊₁σᵢ=σᵢ₊₁σᵢσᵢ₊₁.|integer
group-algebra|definition|Group algebra|For a group G and field k, k[G] consists of finite k-linear combinations of group elements, with multiplication extending the group law bilinearly.|
hopf-algebra|definition|Hopf algebra|An algebra with compatible coproduct and counit, together with an antipode satisfying the axioms that make duals and tensor products of representations possible.|
g2-lie-algebra|definition|Lie algebra 𝔤₂|The 14-dimensional complex simple Lie algebra of exceptional type G₂.|
quantum-g2|definition|Quantum group U_q(𝔤₂)|The Drinfeld–Jimbo quantized enveloping algebra of 𝔤₂; in the braid-generation theorem q is indeterminate and the coefficient field is ℂ(q).|g2-lie-algebra hopf-algebra
seven-dimensional-g2|definition|Seven-dimensional fundamental representation of U_q(𝔤₂)|The irreducible fundamental U_q(𝔤₂)-module of dimension seven, deforming the smallest nontrivial representation of 𝔤₂.|quantum-g2
intertwiner|definition|Intertwiner of algebra representations|A linear map T between modules over an algebra A such that T(av)=aT(v) for every a∈A and v in the source module.|
tensor-power-representation|definition|Tensor power of a Hopf-algebra representation|The representation on V⊗n obtained by applying the iterated coproduct before acting on its n factors.|hopf-algebra
centralizer-algebra|definition|Centralizer algebra of a representation|For an H-module W, End_H(W) is the algebra of linear endomorphisms commuting with H; multiplication is composition.|intertwiner
universal-r-matrix|definition|Universal R-matrix|An invertible element R in a suitable completion of H⊗H that conjugates the coproduct to its opposite and satisfies the two coproduct compatibility identities; on modules, flip∘R gives a braiding.|hopf-algebra braided-category
braid-action-tensor-power|construction|Braid-group action on a tensor power|For an object V in a braided monoidal category, σᵢ acts on V⊗n as the braiding c(V,V) on factors i,i+1 and the identity on all other factors.|braid-group braided-category
strong-multiplicity-free|definition|Strongly multiplicity-free representation|An irreducible highest-weight representation whose weight spaces are one-dimensional and whose weights are totally ordered by the root order.|quantum-g2
g2-spider|definition|Kuperberg's G₂ spider|The ℂ(q)-linear tensor category presented by planar G₂ webs and Kuperberg's local relations. The paper uses its single-edge trivalent presentation generated by the seven-dimensional module.|linear-category monoidal-category
g2-web|definition|G₂ web|A planar trivalent graph with specified boundary endpoints, interpreted as a morphism in the G₂ spider; closed loop components are allowed.|g2-spider
nonelliptic-g2-web|definition|Non-elliptic G₂ web|A G₂ web with no closed loop components and with at least six edges on every internal face.|g2-web
euler-measure|definition|Euler measure of a surface with assigned corner angles|For a surface F with assigned corner angles θᵢ, its Euler measure is e(F)=χ(F)−∑ᵢ(π−θᵢ)/(2π).|
tilting-module|definition|Tilting module for a quantum group|A finite-dimensional module admitting both a filtration by Weyl modules and a filtration by dual Weyl modules.|quantum-g2
g2-web-basis|theorem|Kuperberg's G₂ web-basis theorem|Over ℂ(q), each morphism space in the G₂ spider has a basis consisting of the non-elliptic webs.|nonelliptic-g2-web
g2-spider-equivalence|theorem|Kuperberg's G₂ spider equivalence theorem|Over ℂ(q), the G₂ spider is equivalent, as a braided tensor category, to the category whose objects are tensor powers of the seven-dimensional U_q(𝔤₂)-module and whose morphisms are intertwiners.|g2-spider seven-dimensional-g2 intertwiner braided-category
g2-braid-surjectivity|theorem|Braid generation of the G₂ tensor centralizer|For the seven-dimensional U_q(𝔤₂)-module V over ℂ(q), the R-matrix representation induces a surjective algebra map ℂ(q)[Bₙ]→End_{U_q(𝔤₂)}(V⊗n) for every n.|seven-dimensional-g2 tensor-power-representation centralizer-algebra group-algebra braid-action-tensor-power g2-web-basis g2-spider-equivalence euler-measure
lehrer-zhang-generation|theorem|Lehrer–Zhang braid-generation theorem|For a strongly multiplicity-free irreducible representation V of a generic Drinfeld–Jimbo quantum group, the braid-group image generates End_U(V⊗n) as an algebra for every n.|strong-multiplicity-free braid-action-tensor-power centralizer-algebra
''')

concepts('Fusion categories / fields of definition', '''
fusion-category|definition|Fusion category|A semisimple k-linear rigid monoidal category with finitely many simple objects, finite-dimensional morphism spaces, a k-bilinear tensor product and End(1)=k. Simple objects need not be split.|rigid-category linear-category semisimple-category
split-fusion-category|definition|Split fusion category|A fusion category in which every simple object has endomorphism algebra k.|fusion-category split-simple
scalar-extension-category|definition|Scalar extension of a linear category|For k⊂K, replace each morphism space Hom(X,Y) by Hom(X,Y)⊗_k K, keeping the same objects and extending composition.|linear-category
rational-form|definition|Rational form of a tensor category|A k-linear tensor category C_k whose scalar extension to K becomes equivalent to C_K after idempotent completion.|scalar-extension-category karoubi-envelope monoidal-category
complete-rational-form|definition|Complete rational form of a tensor category|A rational form C_k for which C_k⊗_k K is already idempotent complete, so the equivalence with C_K requires no new summands.|rational-form
cyclotomic-field|definition|Cyclotomic field|A number field ℚ(ζₙ) generated by a primitive nth root of unity.|integer
cyclotomic-integer|definition|Cyclotomic integer|An algebraic integer lying in a cyclotomic field.|cyclotomic-field
galois-conjugate-category|construction|Galois conjugate of a fusion category|Apply a field embedding to the coefficients of the associativity and other structure maps, then extend scalars to ℂ; the result is well-defined up to equivalence.|fusion-category scalar-extension-category
frobenius-perron-dimension|definition|Frobenius–Perron dimension|For a simple object X of a fusion category, FPdim(X) is the spectral radius of its fusion matrix, whose entries record the multiplicities in X⊗Y; extend it additively to other objects.|fusion-category
global-dimension|definition|Global dimension of a fusion category|The sum of the intrinsic squared norms of its simple objects; for a spherical fusion category this is the sum of their squared categorical dimensions.|fusion-category categorical-trace
brauer-splitting|theorem|Brauer's cyclotomic splitting-field theorem|If a finite group G has exponent n, then ℚ(ζₙ) is a splitting field for G: every irreducible complex representation of G has a model over ℚ(ζₙ).|cyclotomic-field group-algebra split-semisimple
fpdim-cyclotomic|theorem|Cyclotomicity of Frobenius–Perron dimensions|The Frobenius–Perron dimension of every object in a fusion category over ℂ is a cyclotomic integer.|frobenius-perron-dimension cyclotomic-integer
global-dimension-cyclotomic|theorem|Cyclotomicity of global dimensions of fusion categories|The global dimension of a fusion category over ℂ is a cyclotomic integer.|global-dimension cyclotomic-integer
''')

concepts('Subfactors / planar algebras', '''
ii1-subfactor|definition|II₁ subfactor|An inclusion N⊂M of von Neumann factors of type II₁.|
jones-index|definition|Jones index|For a II₁ subfactor N⊂M, its index [M:N] is the von Neumann dimension of L²(M) as an N-module, possibly infinite.|ii1-subfactor
principal-even-part|definition|Principal even part of a subfactor|For a finite-index II₁ subfactor N⊂M, the tensor category of N–N bimodules generated by L²(M), closing under finite sums, summands and duals.|ii1-subfactor jones-index rigid-category karoubi-envelope
dual-even-part|definition|Dual even part of a subfactor|For a finite-index II₁ subfactor N⊂M, the tensor category of M–M bimodules generated by L²(M)⊗_N L²(M), closing under finite sums, summands and duals.|ii1-subfactor jones-index rigid-category karoubi-envelope
principal-graph|definition|Principal graphs of a subfactor|The pair of bipartite graphs recording tensoring by the generating N–M bimodule and its dual, with vertices the simple bimodules and edge multiplicities the corresponding fusion multiplicities.|principal-even-part dual-even-part
finite-depth|definition|Finite-depth subfactor|A finite-index subfactor whose principal graphs are finite, equivalently whose even parts have only finitely many simple objects.|principal-graph
haagerup-subfactor|definition|Haagerup subfactor|The finite-depth hyperfinite II₁ subfactor with index (5+√13)/2 and the Haagerup principal graph pair.|finite-depth
extended-haagerup-subfactor|definition|Extended Haagerup subfactor|The finite-depth hyperfinite II₁ subfactor with the extended Haagerup principal graph pair, of index approximately 4.3772.|finite-depth
principal-haagerup-category|definition|Principal Haagerup fusion category|The principal even part of the Haagerup subfactor, considered as a fusion category over ℂ.|haagerup-subfactor principal-even-part fusion-category
dual-haagerup-category|definition|Dual Haagerup fusion category|The dual even part of the Haagerup subfactor, considered as a fusion category over ℂ.|haagerup-subfactor dual-even-part fusion-category
principal-extended-haagerup-category|definition|Principal extended Haagerup fusion category|The principal even part of the extended Haagerup subfactor, considered as a fusion category over ℂ.|extended-haagerup-subfactor principal-even-part fusion-category
dual-extended-haagerup-category|definition|Dual extended Haagerup fusion category|The dual even part of the extended Haagerup subfactor, considered as a fusion category over ℂ.|extended-haagerup-subfactor dual-even-part fusion-category
haagerup-center|definition|Drinfeld center of the Haagerup fusion category|The common braided center of the principal and dual Haagerup fusion categories, with the ribbon structure coming from their subfactor construction.|principal-haagerup-category dual-haagerup-category drinfeld-center ribbon-category
haagerup-planar-algebra|definition|Haagerup planar algebra|The shaded subfactor planar algebra of the Haagerup subfactor. Morrison–Snyder use a rescaled generator and lopsided normalization of it.|haagerup-subfactor shaded-planar-algebra
extended-haagerup-planar-algebra|definition|Extended Haagerup planar algebra|The shaded subfactor planar algebra of the extended Haagerup subfactor. Morrison–Snyder use a rescaled generator and lopsided normalization of it.|extended-haagerup-subfactor shaded-planar-algebra
shaded-planar-tangle|definition|Shaded planar tangle|A disc with interior discs and nonintersecting strings, with an even number of endpoints on each boundary, checkerboard-shaded complementary regions and marked boundary intervals; considered up to the prescribed isotopy.|
shaded-planar-algebra|definition|Shaded planar algebra|Vector spaces P_{n,+},P_{n,−} acted on multilinearly by shaded planar tangles, compatibly with gluing and identity tangles.|shaded-planar-tangle
uncappable|definition|Uncappable element of a planar algebra|A box killed by every operation that caps two adjacent boundary points.|shaded-planar-algebra
rotational-eigenvector|definition|Rotational eigenvector in a planar algebra|A box S satisfying ρ(S)=ωS for the shading-preserving rotation ρ; for an n-box, ω is an nth root of unity.|shaded-planar-algebra
lopsided-planar-algebra|definition|Lopsided planar algebra|A shaded planar algebra normalized so that the shaded contractible circle evaluates to 1; the other circle evaluates to the index.|shaded-planar-algebra
quantum-integer|definition|Quantum integer|The q-integer [n]_q=(qⁿ−q⁻ⁿ)/(q−q⁻¹).|integer
jones-wenzl-idempotent|definition|Jones–Wenzl idempotent|The idempotent fₙ in TLₙ(δ) with identity-diagram coefficient 1 and eᵢfₙ=fₙeᵢ=0 for every adjacent cap–cup generator. It exists for all n at generic δ; special parameters require care.|quantum-integer
noncyclotomic-haagerup|theorem|Non-cyclotomicity of the principal Haagerup fusion categories|The principal even parts of the Haagerup and extended Haagerup subfactors have no complete rational form over any cyclotomic field.|haagerup-subfactor extended-haagerup-subfactor principal-even-part complete-rational-form cyclotomic-field haagerup-fields
haagerup-fields|theorem|Fields of definition of the Haagerup and extended Haagerup fusion categories|For ℓ=0,1 write Hℓᵖ,Hℓᵈ for the principal and dual even parts and Dℓ for the index. Put n=4ℓ+4, choose q with q+q⁻¹=√Dℓ, and let λℓ²=−[n+2]_q/([2]_q²[n]_q). Both even parts have rational forms over ℚ(Dℓ); for ℚ⊂k⊂ℂ, Hℓᵈ has a complete rational form over k iff Dℓ∈k, and Hℓᵖ iff λℓ∈k. The center Z(H₀ᵖ) has a complete rational form as a ribbon category over k iff ζ₃₉∈k.|haagerup-subfactor extended-haagerup-subfactor principal-even-part dual-even-part complete-rational-form lopsided-planar-algebra jones-wenzl-idempotent drinfeld-center ribbon-category quantum-integer
haagerup-galois-conjugates|theorem|Galois conjugates of the Haagerup and extended Haagerup fusion categories|Up to tensor equivalence, the principal Haagerup even part has two Galois conjugates and the principal extended Haagerup even part has three. All the nonoriginal conjugates are nonunitary. The normal closures of their complete fields of definition have Galois groups D₈ (order eight) and C₂×A₄, respectively.|galois-conjugate-category haagerup-fields
''')

concepts('Centers / module categories', '''
half-braiding|definition|Half-braiding|For a fixed object X, a natural family of isomorphisms X⊗Y→Y⊗X compatible with tensor products in Y.|monoidal-category
drinfeld-center|definition|Drinfeld center|The braided category Z(C) of pairs (X,c), where X∈C and c is a half-braiding; morphisms are the maps intertwining those half-braidings.|half-braiding braided-category
center-induction|definition|Induction to the Drinfeld center|The left adjoint I:C→Z(C) of the functor that forgets the half-braiding.|drinfeld-center
module-category|definition|Module category over a tensor category|A category M with an action C×M→M and coherent associativity and unit isomorphisms.|monoidal-category
dual-fusion-category|definition|Dual fusion category|For an indecomposable semisimple module category M over a fusion category C, the category Fun_C(M,M) of module endofunctors, with composition as tensor product.|fusion-category module-category
internal-hom|definition|Internal Hom in a module category|The object Hom_C(M,N) representing X↦Hom_M(X⊗M,N).|module-category
s-matrix|definition|S-matrix of a ribbon fusion category|The matrix indexed by simple objects whose entries are the categorical traces of their double braidings, equivalently the corresponding Hopf-link evaluations.|ribbon-category fusion-category categorical-trace
t-matrix|definition|T-matrix of a ribbon fusion category|The diagonal matrix whose entry at a simple object is the scalar by which its ribbon twist acts.|ribbon-category fusion-category
modular-category|definition|Modular tensor category|A ribbon fusion category whose S-matrix is invertible.|s-matrix
center-base-change|theorem|Rational forms pass to Drinfeld centers|If C_k is a rational form of a fusion category C_K, the natural functor Z(C_k)⊗_k K→Z(C_K) is fully faithful and dominant. Thus Z(C_k) is a braided rational form of Z(C_K), with idempotent completion understood.|rational-form drinfeld-center scalar-extension-category karoubi-envelope
module-dual-base-change|theorem|Rational forms pass to dual fusion categories|For a fusion category D_K with an indecomposable semisimple module category M_K and compatible rational forms D_k,M_k, the induced functor D_k*⊗_k K→D_K* is fully faithful and dominant. Hence D_k* is a rational form of D_K*.|dual-fusion-category internal-hom rational-form
''')


def source(slug,title,authors,year,identifiers,coverage,review,url=None):
    row=dict(slug=slug,title=title,authors=authors,year=year,field='Quantum algebra / tensor categories',
             status='draft' if url else 'catalogued',identifiers=identifiers,coverage=coverage,
             summary=title,dependency_review=review)
    if url:
        local=ROOT/'references'/f'{slug}.pdf'
        row['artifacts']=[dict(url=url,version='Repository full-text snapshot; internal theorem numbering retained',
                               accessed_at='2026-11-12',sha256=hashlib.sha256(local.read_bytes()).hexdigest(),
                               local_path=str(local.relative_to(ROOT)),note='Read for the v3 concept extraction.')]
    SOURCES.append(row)


